import styled from 'styled-components'
export const Card = styled.div`
  padding: 8px;
  border: 1px solid #A1A1A1,
  background-color: #FCFCFC,
  font-size: 24px;
`
export const Contador = styled.span`
  color: #5E5E5E ;
  font-weight: bold;
  display: block;
`
export const Label = styled.span`
  font-size: 14px;
`
